-- Reviewed public issuer facts only. No publication or event promotion.
-- Insert only new ticker/period records; preserve pre-existing aliases and facts.
WITH seed(id,ticker,fiscal_period,company_name,filing_day,source_url,notes) AS (VALUES
('CI|Q3 FY2026','CI','Q3 FY2026','The Cigna Group','2026-11-05'::date,'https://www.sec.gov/Archives/edgar/data/1739940/000173994026000071/ci-20260930.htm','Quarter ended 2026-09-30; source-reviewed partial results; no release/publication timestamp inferred.'),
('NVDA|Q3 FY2027','NVDA','Q3 FY2027','NVIDIA Corporation','2026-11-17'::date,'https://www.sec.gov/Archives/edgar/data/1045810/000104581026000088/q3fy27pr.htm','Quarter ended 2026-10-25; source-reviewed partial results; no release/publication timestamp inferred.'),
('DELL|Q3 FY2027','DELL','Q3 FY2027','Dell Technologies Inc.','2026-11-24'::date,'https://www.sec.gov/Archives/edgar/data/1571996/000157199626000050/exhibit991earnings8kq3fy27.htm','Quarter ended 2026-10-30; source-reviewed partial results; no release/publication timestamp inferred.')
), new_results AS (
 INSERT INTO public.issuer_earnings_results(id,ticker,fiscal_period,company_name,filing_day,source_url,verification_status,verification_notes)
 SELECT s.id,s.ticker,s.fiscal_period,s.company_name,s.filing_day,s.source_url,'partial',s.notes FROM seed s
 WHERE NOT EXISTS(SELECT 1 FROM public.issuer_earnings_results r WHERE r.ticker=s.ticker AND (r.filing_day=s.filing_day OR regexp_replace(r.fiscal_period,'[^0-9]','','g') IN (regexp_replace(s.fiscal_period,'[^0-9]','','g'),left(regexp_replace(s.fiscal_period,'[^0-9]','','g'),1)||right(s.fiscal_period,2),right(s.fiscal_period,4)||'3',right(s.fiscal_period,2)||'3')))
 ON CONFLICT DO NOTHING RETURNING id
), facts(result_id,metric_key,value_numeric,unit,accounting_basis,period_basis,source_url,source_excerpt) AS (VALUES
